package rtyaml

import (
	"compress/gzip"
	"encoding/json"
	"io"
	"os"
	"strings"
	"testing"
)

// corpus rows are generated by testdata/rtgen.py from ruamel.yaml 0.19:
// YAML() with preserve_quotes, load then dump (r0), after assigning a
// tracker block (r1), after deleting the first key (r2).
type rtCase struct {
	Src string            `json:"src"`
	Out []*map[string]any `json:"out"`
}

func loadCorpus(t *testing.T) []rtCase {
	path := os.Getenv("RTYAML_CORPUS")
	var r io.Reader
	if path != "" {
		f, err := os.Open(path)
		if err != nil {
			t.Fatal(err)
		}
		defer f.Close()
		r = f
	} else {
		f, err := os.Open("testdata/corpus.json.gz")
		if err != nil {
			t.Fatal(err)
		}
		defer f.Close()
		gz, err := gzip.NewReader(f)
		if err != nil {
			t.Fatal(err)
		}
		r = gz
	}
	var cases []rtCase
	if err := json.NewDecoder(r).Decode(&cases); err != nil {
		t.Fatal(err)
	}
	return cases
}

func trackerBlock() *Map {
	own := NewMap()
	own.Set("mode", "external_authoritative")
	own.Set("field_owners", NewMap())
	m := NewMap()
	m.Set("provider", "beads")
	m.Set("binding_ref", nil)
	m.Set("project_slug", nil)
	m.Set("display_label", nil)
	m.Set("provider_context", nil)
	m.Set("workspace", "ws")
	m.Set("ownership", own)
	return m
}

func errClass(err error) string {
	msg := err.Error()
	if i := strings.Index(msg, ": "); i > 0 && strings.HasSuffix(msg[:i], "Error") && !strings.Contains(msg[:i], " ") {
		return msg[:i]
	}
	return "EmitterError"
}

func TestRoundTripCorpus(t *testing.T) {
	cases := loadCorpus(t)
	fails := 0
	for i, c := range cases {
		for edit, want := range c.Out {
			if want == nil {
				continue
			}
			data, err := LoadString(c.Src)
			if err != nil {
				t.Errorf("case %d: load: %v\nsrc: %q", i, err, c.Src)
				fails++
				break
			}
			switch edit {
			case 1:
				m, ok := data.(*Map)
				if !ok {
					t.Errorf("case %d: root is %T, want map", i, data)
					continue
				}
				m.Set("tracker", trackerBlock())
			case 2:
				m, ok := data.(*Map)
				if !ok || m.Len() == 0 {
					t.Errorf("case %d: root is %T, want non-empty map", i, data)
					continue
				}
				m.Delete(m.Keys()[0])
			}
			got, err := Dump(data)
			w := *want
			if e, ok := w["err"].(string); ok {
				cls, _, _ := strings.Cut(e, "|")
				if err == nil || errClass(err) != cls {
					t.Errorf("case %d edit %d: want error %s, got %v / %q\nsrc: %q", i, edit, e, err, got, c.Src)
					fails++
				}
				continue
			}
			if err != nil {
				t.Errorf("case %d edit %d: dump error %v\nsrc: %q", i, edit, err, c.Src)
				fails++
				continue
			}
			if got != w["ok"].(string) {
				t.Errorf("case %d edit %d:\nsrc:  %q\nwant: %q\ngot:  %q", i, edit, c.Src, w["ok"], got)
				fails++
			}
		}
		if i == len(cases)-1 {
			t.Logf("%d cases", len(cases))
		}
		if fails > 30 {
			t.Fatal("too many failures")
		}
	}
}
